-- Stable employee identities; do not rewrite any existing loan, payroll or bank movement.
DO $$ DECLARE e record; new_party bigint; seq text; seq_last bigint; BEGIN
 seq := pg_get_serial_sequence('public.parties', 'id');
 IF seq IS NULL THEN RAISE EXCEPTION 'Parties ID sequence missing'; END IF;
 EXECUTE format('SELECT last_value FROM %s', seq) INTO seq_last;
 PERFORM setval(seq, GREATEST(seq_last, COALESCE((SELECT max(id) FROM public.parties), 1)), true);
 FOR e IN SELECT * FROM public.employees WHERE party_id IS NULL ORDER BY id FOR UPDATE LOOP
  INSERT INTO public.parties(name,types,email,phone,status,created_at,updated_at)
    VALUES(e.full_name,'employee',e.personal_email,e.mobile_phone,'active',now(),now()) RETURNING id INTO new_party;
  UPDATE public.employees SET party_id=new_party WHERE id=e.id;
  INSERT INTO public.activity_logs(model_id,model_type,action,new_value,created_at,updated_at)
    VALUES(new_party,'Party','Created employee party during release',json_build_object('employee_id',e.id,'types','employee'),now(),now());
 END LOOP;
END $$;
INSERT INTO public.migrations(migration,batch) SELECT v.name, (SELECT COALESCE(max(batch),0)+1 FROM public.migrations) FROM (VALUES ('2026_11_06_000001_align_finance_schema'),('2026_11_06_000002_add_loan_type_to_loans_table'),('2026_11_06_000003_create_loan_refinancing_links'),('2026_11_06_000004_align_legacy_journal_headers'),('2026_11_06_000006_create_payroll_tables'),('2026_11_06_000007_align_payroll_cash_transactions'),('2026_11_06_000008_add_payroll_input_mode_to_salary_components'),('2026_11_06_000009_schedule_salary_advance_recoveries'),('2026_11_06_000010_link_employees_to_parties'),('2026_11_06_000011_create_private_document_files'),('2026_11_06_000012_align_legacy_optional_fields')) AS v(name) WHERE NOT EXISTS (SELECT 1 FROM public.migrations m WHERE m.migration=v.name);
COMMIT;
